package dev.raf.radar;
import java.io.*;import java.util.*;import java.util.function.LongSupplier;import org.json.*;
/** Owner-scoped names/positions; resend only changes, survive offline rename and move. */
final class SourceQueue {
 final File file;final LongSupplier clock;JSONObject entries=new JSONObject();
 SourceQueue(File file,LongSupplier clock){this.file=file;this.clock=clock;try{entries=new JSONObject(DiagnosticJournal.read(file));}catch(Exception ignored){}}
 synchronized void synchronize(int owner,List<Point> points)throws Exception{if(owner<1)return;boolean changed=false;for(Point p:points){if(p.dynamic)continue;if(p.id==null||!p.id.matches("[-a-zA-Z0-9_]{1,80}")||!Double.isFinite(p.lat)||Math.abs(p.lat)>85||!Double.isFinite(p.lon)||Math.abs(p.lon)>180)continue;String key=owner+":"+p.id;JSONObject previous=entries.optJSONObject(key);String name=p.name==null?"":java.text.Normalizer.normalize(p.name,java.text.Normalizer.Form.NFC).replaceAll("[\\p{Cntrl}]","").trim();if(name.codePointCount(0,name.length())>80)name=name.substring(0,name.offsetByCodePoints(0,80));if(name.isEmpty())continue;if(previous!=null&&name.equals(previous.optString("name"))&&p.lat==previous.optDouble("lat")&&p.lon==previous.optDouble("lon"))continue;long revision=Math.max(1,Math.max(clock.getAsLong(),previous==null?1:previous.optLong("revision")+1));entries.put(key,new JSONObject().put("owner",owner).put("sourcePoint",p.id).put("name",name).put("lat",p.lat).put("lon",p.lon).put("revision",revision).put("pending",true));changed=true;}if(changed)save();}
 synchronized JSONArray batch(int owner)throws Exception{JSONArray out=new JSONArray();Iterator<String> keys=entries.keys();while(keys.hasNext()&&out.length()<20){JSONObject e=entries.getJSONObject(keys.next());if(e.optInt("owner")==owner&&e.optBoolean("pending")){JSONObject row=new JSONObject(e.toString());row.remove("owner");row.remove("pending");out.put(row);}}return out;}
 synchronized void acknowledge(int owner,JSONArray accepted)throws Exception{if(accepted==null)return;for(int i=0;i<accepted.length();i++){JSONObject row=accepted.optJSONObject(i);if(row==null)continue;JSONObject entry=entries.optJSONObject(owner+":"+row.optString("sourcePoint"));if(entry!=null&&entry.optLong("revision")==row.optLong("revision"))entry.put("pending",false);}save();}
 void save()throws Exception{file.getParentFile().mkdirs();DiagnosticJournal.write(file,entries.toString());}
}
